-- 取回 meas
WITH "base" AS (SELECT "ds_orders"."Row ID" AS "f_row_id", "ds_orders"."Order ID" AS "f_order_id", "ds_orders"."Order Date" AS "f_order_date", "ds_orders"."Ship Date" AS "f_ship_date", "ds_orders"."Ship Mode" AS "f_ship_mode", "ds_orders"."Customer ID" AS "f_customer_id", "ds_orders"."Customer Name" AS "f_customer_name", "ds_orders"."Segment" AS "f_segment", "ds_orders"."Country/Region" AS "f_country_region", "ds_orders"."City" AS "f_city", "ds_orders"."State/Province" AS "f_state_province", "ds_orders"."Postal Code" AS "f_postal_code", "ds_orders"."Region" AS "f_region", "ds_orders"."Product ID" AS "f_product_id", "ds_orders"."Category" AS "f_category", "ds_orders"."Sub-Category" AS "f_sub_category", "ds_orders"."Product Name" AS "f_product_name", "ds_orders"."Sales" AS "f_sales", "ds_orders"."Quantity" AS "f_quantity", "ds_orders"."Discount" AS "f_discount", "ds_orders"."Profit" AS "f_profit" FROM "AwsDataCatalog"."sales"."ds_orders" AS "ds_orders"), "src" AS (SELECT * FROM "base" WHERE ("f_country_region" IN ('United States'))), "dimf" AS (SELECT * FROM "src" WHERE ("f_region" IS NULL OR NOT ("f_region" IN ('Central')))), "lod" AS (SELECT "f_region" AS "__d0", "f_order_id" AS "__d1", SUM("f_sales") AS "__v" FROM "dimf" GROUP BY 1, 2), "dimf_ext" AS (SELECT "r".*, "l0"."__v" AS "__lod_1" FROM "dimf" AS "r" LEFT JOIN "lod" AS "l0" ON "r"."f_region" IS NOT DISTINCT FROM "l0"."__d0" AND "r"."f_order_id" IS NOT DISTINCT FROM "l0"."__d1"), "lod_agg" AS (SELECT "f_region" AS "__k0" FROM "dimf_ext" GROUP BY 1), "combos" AS (SELECT DISTINCT "f_region" AS "__g0", "f_order_id" AS "__g1", "__lod_1" FROM "dimf_ext"), "combo_agg" AS (SELECT "__g0" AS "__k0", MAX("__lod_1") AS "__a0" FROM "combos" GROUP BY 1), "lod_agg_1" AS (SELECT "b".*, "c0"."__a0" FROM "lod_agg" AS "b" LEFT JOIN "combo_agg" AS "c0" ON "b"."__k0" IS NOT DISTINCT FROM "c0"."__k0"), "lod_1" AS (SELECT "__k0", "__a0" AS "__v" FROM "lod_agg_1"), "dimf_ext_1" AS (SELECT "r".*, "l0"."__v" AS "__lod_0" FROM "dimf_ext" AS "r" LEFT JOIN "lod_1" AS "l0" ON "r"."f_region" IS NOT DISTINCT FROM "l0"."__k0"), "agg" AS (SELECT "f_region" AS "__k0", "f_category" AS "__k1" FROM "dimf_ext_1" GROUP BY 1, 2), "combos_1" AS (SELECT DISTINCT "f_region" AS "__g0", "f_category" AS "__g1", "__lod_0" FROM "dimf_ext_1"), "combo_agg_1" AS (SELECT "__g0" AS "__k0", "__g1" AS "__k1", SUM(("__lod_0")) AS "__a0" FROM "combos_1" GROUP BY 1, 2), "agg_1" AS (SELECT "b".*, "c0"."__a0" FROM "agg" AS "b" LEFT JOIN "combo_agg_1" AS "c0" ON "b"."__k0" IS NOT DISTINCT FROM "c0"."__k0" AND "b"."__k1" IS NOT DISTINCT FROM "c0"."__k1"), "meas" AS (SELECT *, "__a0" AS "__m0" FROM "agg_1") SELECT * FROM "meas"
